package android.util;import java.io.*;import java.nio.file.*;public class AtomicFile {private final File f;public AtomicFile(File f){this.f=f;}public void delete(){f.delete();new File(f+".new").delete();new File(f+".bak").delete();}public File getBaseFile(){return f;}public byte[] readFully()throws Exception{return Files.readAllBytes(f.toPath());}public FileOutputStream startWrite()throws Exception{return new FileOutputStream(f+".new");}public void finishWrite(FileOutputStream out)throws Exception{out.close();Files.move(new File(f+".new").toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}public void failWrite(FileOutputStream out)throws Exception{out.close();new File(f+".new").delete();}}